"use client";
/* Squish, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Squish(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("squish"); }, []);
  return React.createElement("piix-pal", { "pal": "squish", ...piixAttrs(props) });
}

export default Squish;
